#nullable enable // autogenerated

using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Effects;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Projectiles
{
    [AutoEntityBehaviourDefinition(VanillaProjectileNames.meowmereProjectile)]
    public class MeowmereProjectile : EntityBehaviourDefinition
    {
        public MeowmereProjectile(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            var position = entity.Position;
            var velocity = entity.Velocity;
            int bounceTimes = 0;
            if (position.x < LEFT_BORDER)
            {
                position.x = LEFT_BORDER;
                velocity.x *= -1;
                bounceTimes++;
            }
            if (position.x > RIGHT_BORDER)
            {
                position.x = RIGHT_BORDER;
                velocity.x *= -1;
                bounceTimes++;
            }
            if (position.z < DOWN_BORDER)
            {
                position.z = DOWN_BORDER;
                velocity.z *= -1;
                bounceTimes++;
            }
            if (position.z > UP_BORDER)
            {
                position.z = UP_BORDER;
                velocity.z *= -1;
                bounceTimes++;
            }
            entity.Position = position;
            entity.Velocity = velocity;

            for (int i = 0; i < bounceTimes; i++)
            {
                OnBounce(entity);
            }
        }
        public override void PostContactGround(Entity entity, Vector3 velocity)
        {
            base.PostContactGround(entity, velocity);
            velocity.y *= -1;
            velocity.y += 1f;
            entity.Velocity = velocity;
            OnBounce(entity);
        }
        protected virtual void OnBounce(Entity entity)
        {
            entity.PlaySound(VanillaSoundID.meowmere, entity.RNG.Next(0.8f, 1.25f), volume: 0.5f);

            BlastEffect(entity);

            var t = 1 - (float)entity.Timeout / entity.GetMaxTimeout();
            var radius = Mathf.Lerp(RADIUS_MIN, RADIUS_MAX, t);
            var effects = new DamageEffectList(VanillaDamageEffects.EXPLOSION);
            entity.Explode(entity.GetCenter(), radius, entity.GetFaction(), entity.GetDamage(), effects);
        }
        public override void PostDeath(Entity entity, DeathInfo deathInfo)
        {
            base.PostDeath(entity, deathInfo);
            if (entity.WillRemoveOnDeath(deathInfo))
                return;
            BlastEffect(entity);
        }
        private void BlastEffect(Entity entity)
        {
            var t = 1 - (float)entity.Timeout / entity.GetMaxTimeout();
            var hue = t;
            var saturation = 0.2f;
            var brightness = 1;
            var color = Color.HSVToRGB(hue, saturation, brightness);
            var radius = Mathf.Lerp(RADIUS_MIN, RADIUS_MAX, t);
            var center = entity.GetCenter();
            FireworkBlast.SpawnFireworkBlast(entity, center, radius, color);
        }
        public const float RADIUS_MIN = 40f;
        public const float RADIUS_MAX = 80f;
        public const float LEFT_BORDER = LevelPositions.PROJECTILE_LEFT_BORDER + 80;
        public const float RIGHT_BORDER = LevelPositions.PROJECTILE_RIGHT_BORDER - 80;
        public const float DOWN_BORDER = LevelPositions.PROJECTILE_DOWN_BORDER + 80;
        public const float UP_BORDER = LevelPositions.PROJECTILE_UP_BORDER - 80;
    }
}
